before.lib/documents.ex:
defmodule Documents do
  @doc "Delete only an existing document owned by the authenticated user."
  def delete(store, id, user) do
    Agent.get_and_update(store, fn rows ->
      case Map.fetch(rows, id) do
        :error -> {{:error, :not_found}, rows}
        {:ok, row} ->
          if row.owner == user do
            {:ok, Map.delete(rows, id)}
          else
            {{:error, :unauthorized}, rows}
          end
      end
    end)
  end
end

